const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const categories=[['Cars','🚘','Comfort for every kind of journey'],['SUVs','🚙','Room for the whole crew'],['Bikes','🏍️','Take the scenic route'],['Scooters','🛵','Zip through the city'],['Bicycles','🚲','Slow down and see more'],['Vans and Cargo','🚐','Bring it all along']];
let me=null, vehicles=[], showCount=8, geo=null, socket=null, currentChat=null, map=null;
let vehicleMarker=null;
const money=n=>'₹'+Number(n).toLocaleString('en-IN');
function notify(message,type='success'){const node=document.createElement('div');node.className='toast '+type;node.textContent=message;$('#toasts').append(node);setTimeout(()=>node.remove(),3600)}
async function api(path,options={}){const res=await fetch(path,{credentials:'same-origin',...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(options.headers||{})}});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||'Something went wrong.');return data}
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderCategories(){ $('#categoryGrid').innerHTML=categories.map(([name,emoji,desc])=>`<button class="category-card" data-category="${name}"><div class="category-emoji">${emoji}</div><h3>${name}</h3><p>${desc}</p></button>`).join(''); $$('.category-card').forEach(el=>el.onclick=()=>{const val=el.dataset.category;$('#categorySelect').value=val;$('#heroCategory').value=val;loadVehicles();$('#vehicles').scrollIntoView({behavior:'smooth'});$$('.category-card').forEach(x=>x.classList.toggle('selected',x===el))})}
async function loadVehicles(){const params=new URLSearchParams();if($('#queryInput').value.trim())params.set('q',$('#queryInput').value.trim());if($('#categorySelect').value)params.set('category',$('#categorySelect').value);params.set('max',$('#priceInput').value||'1000');params.set('sort',$('#sortSelect').value);if($('#verifiedOnly')?.checked)params.set('verifiedOnly','1');if(geo){params.set('lat',geo.lat);params.set('lng',geo.lng)}$('#resultsCount').textContent='Finding your next ride...';try{vehicles=await api('/api/vehicles?'+params);renderVehicles()}catch(e){$('#vehicleGrid').innerHTML=`<div class="empty-state">Could not load rides. ${escapeHtml(e.message)}</div>`}}
function renderVehicles(){const shown=vehicles.slice(0,showCount);$('#resultsCount').textContent=`${vehicles.length} ride${vehicles.length===1?'':'s'} ready for you`;$('#vehicleGrid').innerHTML=shown.length?shown.map(v=>`<article class="vehicle-card" data-id="${v.id}"><div class="vehicle-photo"><img loading="lazy" src="${escapeHtml(v.image)}" alt="${escapeHtml(v.name)}" onerror="this.src='https://images.unsplash.com/photo-1492144534655-ae79c964c9d7?auto=format&fit=crop&w=900&q=80'"><span class="photo-category">${escapeHtml(v.category)}</span><button class="heart-btn" data-fav="${v.id}" aria-label="Save ride">♡</button></div><div class="vehicle-info"><div class="vehicle-title"><h3>${escapeHtml(v.name)}</h3><span class="rating">★ 4.9</span></div><p class="vehicle-location">⌖ ${escapeHtml(v.location)}${v.distance!=null?` · ${v.distance.toFixed(1)} km`:''}</p><div class="vehicle-line"><span class="vehicle-price">${money(v.price)} <small>/ hour</small></span><span class="owner-mini"><img src="${escapeHtml(v.owner_avatar||'https://i.pravatar.cc/80?img=12')}" alt=""> ${escapeHtml(v.owner_name)} ${v.owner_verified?'✓ Verified':''} ${v.owner_trust_score?`· ${v.owner_trust_score}`:''}</span></div></div></article>`).join(''):'<div class="empty-state"><span>⌕</span>No rides match those filters yet. Try a different search.</div>';$('#loadMore').style.display=vehicles.length>showCount?'flex':'none';$$('.vehicle-card').forEach(el=>el.onclick=()=>openVehicle(el.dataset.id));$$('.heart-btn').forEach(el=>el.onclick=e=>{e.stopPropagation();el.classList.toggle('saved');el.textContent=el.classList.contains('saved')?'♥':'♡'})}
function openModal(html,wide=false){$('#modalContent').innerHTML=html;$('#modal').classList.remove('dashboard-modal');$('#modalBackdrop').classList.remove('dashboard-backdrop');$('#modal').classList.toggle('wide',wide);$('#modalBackdrop').classList.add('open');document.body.style.overflow='hidden'}
function closeModal(){$('#modalBackdrop').classList.remove('open','dashboard-backdrop');$('#modal').classList.remove('dashboard-modal');document.body.style.overflow='';if(map){map.remove();map=null}}
window.closeModal=closeModal;window.notify=notify;
function authForm(kind='login'){const registering=kind==='register';openModal(`<div class="auth-head"><a class="brand" href="#home"><span class="brand-mark"><svg viewBox="0 0 32 32"><path d="M4 18.5 7.5 10c.5-1.2 1.7-2 3-2h11c1.3 0 2.5.8 3 2l3.5 8.5v7h-3v-3H7v3H4v-7.5Zm4.1-1.3h15.8l-2.3-5.4H10.4l-2.3 5.4ZM9 22a2 2 0 1 0 0-4 2 2 0 0 0 0 4Zm14 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z"/></svg></span><span>rent<span class="brand-ride">ride</span></span></a><h2>${registering?'Your next chapter starts here.':'Welcome back.'}</h2><p>${registering?'Create an account and get moving.':'Sign in to continue your journey.'}</p></div><form id="authForm" class="form-stack">${registering?`<label>Full name<input name="name" required placeholder="Your name"></label><div class="role-pick"><button type="button" class="active" data-role="renter">I want to rent</button><button type="button" data-role="owner">I own a vehicle</button></div><input type="hidden" name="role" value="renter">`:''}<label>Email address<input name="email" type="email" required autocomplete="email" placeholder="you@example.com"></label><label>Password<input name="password" type="password" minlength="8" required autocomplete="${registering?'new-password':'current-password'}" placeholder="${registering?'At least 8 characters':'Your password'}"></label><button class="btn btn-dark" type="submit">${registering?'Create my account':'Log in'} <span>→</span></button></form><p class="auth-switch">${registering?'Already have an account?':'New to RentRide?'} <button id="authSwitch">${registering?'Log in':'Create an account'}</button></p>`);$$('.role-pick button').forEach(b=>b.onclick=()=>{$$('.role-pick button').forEach(x=>x.classList.toggle('active',x===b));$('input[name=role]').value=b.dataset.role});$('#authSwitch').onclick=()=>authForm(registering?'login':'register');$('#authForm').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));try{const data=await api('/api/auth/'+(registering?'register':'login'),{method:'POST',body:JSON.stringify(body)});me=data.user;closeModal();updateHeader();connectSocket();notify(`Welcome${me.name?`, ${me.name.split(' ')[0]}`:''}!`);if(me.is_owner)openDashboard('overview','owner')}catch(err){notify(err.message,'error')}}}
window.openAuth=authForm;
window.openOwnerAuth=()=>{authForm('register');const ownerChoice=$('.role-pick [data-role="owner"]');if(ownerChoice)ownerChoice.click()};
function updateHeader(){const h=$('#headerActions');if(!me){h.innerHTML=`<button class="icon-btn" aria-label="Notifications" onclick="notify('You’re all caught up!','info')"><svg viewBox="0 0 24 24"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg></button><button class="btn btn-outline" onclick="openAuth('login')">Log in</button><button class="btn btn-dark" onclick="openAuth('register')">Sign up <span>↗</span></button>`;return}h.innerHTML=`<button class="icon-btn" title="My RentRide dashboard" onclick="openDashboard()">▤</button>${me.is_owner?'<button class="btn btn-outline" onclick="openDashboard()">Owner workspace</button>':'<button class="btn btn-outline" onclick="openDashboard()">My bookings</button>'}<button class="btn btn-dark" onclick="logout()">${escapeHtml(me.name.split(' ')[0])} · Sign out</button>`}
window.logout=async()=>{try{await api('/api/auth/logout',{method:'POST',body:'{}'});me=null;updateHeader();if(socket)socket.disconnect();notify('You have signed out.')}catch(e){notify(e.message,'error')}};
window.enableOwnerMode=async()=>{try{const data=await api('/api/auth/owner-mode',{method:'POST',body:'{}'});me=data.user;updateHeader();connectSocket();notify('Owner workspace enabled for your account.');openDashboard('overview','owner')}catch(e){notify(e.message,'error')}};
window.ownerCta=()=>me?me.is_owner?openDashboard('overview','owner'):openModal(`<div class="owner-join"><div class="auth-head"><div class="brand-mark" style="margin:auto"><svg viewBox="0 0 32 32"><path d="M4 18.5 7.5 10c.5-1.2 1.7-2 3-2h11c1.3 0 2.5.8 3 2l3.5 8.5v7h-3v-3H7v3H4v-7.5Zm4.1-1.3h15.8l-2.3-5.4H10.4l-2.3 5.4ZM9 22a2 2 0 1 0 0-4 2 2 0 0 0 0 4Zm14 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z"/></svg></div><h2>List a ride with this account</h2><p>You can rent and list vehicles using the same email. Turn on your owner workspace and keep both dashboards connected to your bookings.</p></div><button class="btn btn-dark" style="width:100%" onclick="enableOwnerMode()">Enable owner workspace <span>→</span></button><p class="auth-switch">Already have another owner account? <button onclick="logout().then(()=>openAuth('login'))">Sign in to it</button></p></div>`):openOwnerAuth();
async function openVehicle(id){try{const v=await api('/api/vehicles/'+id),isMine=Number(me?.id)===Number(v.owner_id);const bookingControls=isMine?`<div class="own-listing-note"><b>This is your vehicle</b><span>To book another ride, return to Explore. You can edit this listing from your owner workspace.</span><button class="btn btn-dark" id="manageOwnVehicle">Manage my listing <span>→</span></button></div>`:`<div class="form-row" style="margin-bottom:10px"><label class="form-stack" style="gap:5px;font-size:9px">Start time<input id="bookingDate" type="datetime-local" required style="height:39px;border:1px solid #e7e5ee;border-radius:8px;padding:0 9px;font-size:10px"></label><label class="form-stack" style="gap:5px;font-size:9px">Hours<input id="bookingHours" type="number" min="1" max="168" value="3" style="height:39px;border:1px solid #e7e5ee;border-radius:8px;padding:0 9px;font-size:10px"></label></div><div class="book-total">Estimated total <strong id="bookTotal">${money(v.price*3)}</strong> <span>· owner confirms your request</span></div><div class="book-row"><button class="btn btn-dark" id="bookNow" style="flex:1">Request this ride <span>→</span></button></div>`;openModal(`<img class="detail-cover" src="${escapeHtml(v.image)}" alt="${escapeHtml(v.name)}"><div class="detail-head"><div><h2>${escapeHtml(v.name)}</h2><p>⌖ ${escapeHtml(v.location)} · ${v.model_year} · <span class="rating">★ 4.9</span></p></div><div class="detail-price">${money(v.price)}<small> / hour</small></div></div><div class="spec-row"><span class="spec-chip">♙ ${v.seats} seats</span><span class="spec-chip">⚙ ${escapeHtml(v.transmission)}</span><span class="spec-chip">♨ ${escapeHtml(v.fuel)}</span><span class="spec-chip">◷ ${v.model_year} model</span></div><p class="detail-desc">${escapeHtml(v.description)}</p><div class="owner-profile"><img src="${escapeHtml(v.owner_avatar)}" alt=""><span><b>${escapeHtml(v.owner_name)}</b><small>Verified owner · usually responds quickly</small></span>${v.owner_verified?'<span class="own-listing-badge">✓ Verified owner</span>':''}<span class="own-listing-badge">${v.owner_trust_score||'New'} · ${escapeHtml(v.owner_tier||'Host')}</span>${isMine?'<span class="own-listing-badge">Your listing</span>':'<button class="small-btn primary" style="margin-left:auto" id="chatOwner">Message owner ↗</button>'}</div><div id="vehicleMap" class="map-box"></div>${bookingControls}`,true);if(isMine){$('#manageOwnVehicle').onclick=()=>{closeModal();openDashboard('vehicles','owner')};return}const dt=new Date(Date.now()+2*3600000);dt.setMinutes(Math.ceil(dt.getMinutes()/15)*15,0,0);$('#bookingDate').value=new Date(dt.getTime()-dt.getTimezoneOffset()*60000).toISOString().slice(0,16);const total=()=>$('#bookTotal').textContent=money(v.price*(Number($('#bookingHours').value)||0));$('#bookingHours').oninput=total;setTimeout(()=>{if(window.L){map=L.map('vehicleMap').setView([v.lat,v.lng],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);L.marker([v.lat,v.lng]).addTo(map).bindPopup(escapeHtml(v.location)).openPopup()}},150);$('#chatOwner').onclick=()=>startChat(v);$('#bookNow').onclick=async()=>{if(!me){closeModal();authForm('login');return}try{const start=new Date($('#bookingDate').value);if(!Number.isFinite(start.getTime())||start.getTime()<Date.now()){notify('Choose a start time in the future.','error');return}await api('/api/bookings',{method:'POST',body:JSON.stringify({vehicle_id:v.id,start_at:start.toISOString(),hours:Number($('#bookingHours').value)})});notify('Booking request sent! The owner will respond soon.');closeModal()}catch(e){notify(e.message,'error')}}}catch(e){notify(e.message,'error')}}
function connectSocket(){if(!me||!window.io)return;if(socket)socket.disconnect();socket=io({withCredentials:true});socket.on('connect_error',()=>{});socket.on('message:new',msg=>{if(currentChat&&Number(currentChat.id)===Number(msg.vehicle_id))appendMessage(msg)});socket.on('chat:new',msg=>{if(currentChat&&Number(currentChat.id)===Number(msg.vehicle_id))appendMessage(msg);if(document.hidden){document.title='(1) New message - RentRide';if('Notification' in window&&Notification.permission==='granted')new Notification('New message from '+(msg.sender_name||'RentRide'),{body:String(msg.body||'').slice(0,60)})}})}
function appendMessage(msg){const box=$('#chatMessages');if(!box)return;const div=document.createElement('div');div.className='chat-msg'+(Number(msg.sender_id)===Number(me.id)?' mine':'');div.innerHTML=`${escapeHtml(msg.body)}<small>${escapeHtml(msg.sender_name||'')} · ${new Date(msg.created_at+'Z').toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}</small>${msg.kind==='offer'&&msg.offer?`<p>Offer status: ${escapeHtml(msg.offer.status)} · ${money(msg.offer.price_per_hour)}/hr</p>${msg.offer.status==='accepted'&&Number(msg.offer.renter_id)===Number(me.id)?`<button class="small-btn primary" data-book-agreed="${msg.offer.id}">Book at agreed price</button>`:''}${msg.offer.status==='pending'&&Number(msg.offer.created_by)!==Number(me.id)?`<button class="small-btn primary" data-offer-action="accept" data-offer-id="${msg.offer.id}">Accept</button> <button class="small-btn" data-offer-action="counter" data-offer-id="${msg.offer.id}">Counter</button> <button class="small-btn danger" data-offer-action="reject" data-offer-id="${msg.offer.id}">Reject</button>`:''}`:''}`;box.append(div);box.scrollTop=box.scrollHeight;div.querySelector('[data-book-agreed]')?.addEventListener('click',async()=>{const start=new Date(Date.now()+2*3600000).toISOString(),hours=Number(msg.offer.hours)||3;try{await api('/api/bookings',{method:'POST',body:JSON.stringify({vehicle_id:msg.offer.vehicle_id,start_at:start,hours,offer_id:msg.offer.id})});notify('Booking sent at the agreed rate.')}catch(e){notify(e.message,'error')}});div.querySelectorAll('[data-offer-action]').forEach(btn=>btn.onclick=async()=>{try{let body={action:btn.dataset.offerAction};if(body.action==='counter'){const price=Number(prompt('Your counter price per hour (₹)'));if(!price)return;body.price_per_hour=price}await api('/api/offers/'+btn.dataset.offerId,{method:'PATCH',body:JSON.stringify(body)});notify('Offer updated.')}catch(e){notify(e.message,'error')}})}
async function startChat(v){if(!me){closeModal();authForm('login');return}if(me.role==='owner'&&me.id!==v.owner_id){notify('Owners can message renters from a booking conversation.','info');return}try{const messages=await api('/api/messages/'+v.id);currentChat=v;socket?.emit('chat:join');$('#chatDock').innerHTML=`<section class="chat-bubble"><div class="chat-head"><span><b>${escapeHtml(v.owner_name)}</b><small>${escapeHtml(v.name)} · RentRide chat</small></span><button id="chatClose">×</button></div><button id="makeOffer" class="small-btn primary" style="margin:8px">Make an offer</button><div class="chat-messages" id="chatMessages"></div><form class="chat-compose" id="chatCompose"><input id="chatInput" placeholder="Write a message…" autocomplete="off"><button aria-label="Send">➤</button></form></section>`;messages.forEach(appendMessage);api('/api/conversations',{method:'POST',body:JSON.stringify({vehicle_id:v.id})}).then(c=>api(`/api/conversations/${c.id}/offers`).then(items=>items.forEach(o=>appendMessage({id:'offer-'+o.id,vehicle_id:v.id,sender_id:o.created_by,sender_name:o.creator_name,body:`Offer: ₹${o.price_per_hour}/hr`,created_at:o.created_at,kind:'offer',offer:o})))).catch(()=>{});$('#makeOffer').onclick=async()=>{if(me.role!=='renter'){notify('Only the renter can start an offer.','info');return}const price=Number(prompt('Your hourly offer in rupees'));if(!price)return;const hours=Number(prompt('Rental hours (optional, leave blank for flexible)')||0);try{const c=await api('/api/conversations',{method:'POST',body:JSON.stringify({vehicle_id:v.id})});await api('/api/offers',{method:'POST',body:JSON.stringify({conversation_id:c.id,price_per_hour:price,...(hours?{hours}:{})})});notify('Offer sent to the owner.')}catch(e){notify(e.message,'error')}};$('#chatClose').onclick=()=>{$('#chatDock').innerHTML='';currentChat=null};$('#chatCompose').onsubmit=e=>{e.preventDefault();const body=$('#chatInput').value.trim();if(!body)return;if(!socket||!socket.connected){notify('Chat connection is offline. Refresh and try again.','error');return}socket.emit('chat:send',{vehicleId:v.id,body},r=>{if(!r.ok)notify(r.error,'error')});$('#chatInput').value=''};closeModal()}catch(e){if(e.message.includes('Start a booking request'))notify('Send a booking request first to open a chat with this owner.','info');else notify(e.message,'error')}}
async function openDashboard(tab='overview',view='auto'){if(!me){authForm('login');return}try{const isOwner=view==='owner'||(view==='auto'&&me.is_owner);const [bookings,all]=await Promise.all([api('/api/bookings?view='+(isOwner?'owner':'renter')),api(isOwner?'/api/owner/vehicles':'/api/vehicles?owner='+me.id)]);let active=tab;const render=()=>{let content='';if(isOwner&&active==='overview'){const pending=bookings.filter(b=>b.status==='pending').length;content=`<div class="stats-grid"><div class="stat-card"><small>YOUR VEHICLES</small><b>${all.length}</b></div><div class="stat-card"><small>BOOKING REQUESTS</small><b>${pending}</b></div><div class="stat-card"><small>COMPLETED BOOKINGS</small><b>${bookings.filter(b=>b.status==='accepted').length}</b></div></div><div class="dash-section-heading"><b>Your vehicle listings</b><button class="small-btn primary" id="addVehicle">+ Add a vehicle</button></div>${inventoryList(all)}`}
if(!isOwner&&active==='overview'){const pending=bookings.filter(b=>b.status==='pending').length,accepted=bookings.filter(b=>b.status==='accepted').length;content=`<div class="renter-welcome"><span class="eyebrow">YOUR RENTRIDE</span><h2>Ready for your next trip, ${escapeHtml(me.name.split(' ')[0])}?</h2><p>Manage your ride requests here, or find something perfect for the road ahead.</p><button class="btn btn-dark" id="exploreRides">Explore available rides <span>→</span></button></div><div class="stats-grid"><div class="stat-card"><small>ALL REQUESTS</small><b>${bookings.length}</b></div><div class="stat-card"><small>WAITING FOR OWNER</small><b>${pending}</b></div><div class="stat-card"><small>CONFIRMED RIDES</small><b>${accepted}</b></div></div><div class="dash-section-heading"><b>Recent booking activity</b><button class="small-btn primary" data-tab="bookings">View all bookings →</button></div>${bookingList(bookings.slice(0,3),false)}`}
if(isOwner&&active==='vehicles')content=`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><span class="inline-note">${all.length} listed vehicle${all.length===1?'':'s'}</span><button class="small-btn primary" id="addVehicle">+ Add a vehicle</button></div>${inventoryList(all)}`;
if((isOwner&&active==='bookings')||(!isOwner&&active==='bookings'))content=bookingList(bookings,isOwner);
if(isOwner&&active==='messages')content=`<div id="inboxList" class="empty-state"><span>✉</span>Loading your inbox…</div>`;
openModal(`<section class="dash-shell ${isOwner?'owner-workspace':'renter-workspace'}"><aside class="dash-sidebar"><a class="brand dash-brand" href="#home" onclick="closeModal()"><span class="brand-mark"><svg viewBox="0 0 32 32"><path d="M4 18.5 7.5 10c.5-1.2 1.7-2 3-2h11c1.3 0 2.5.8 3 2l3.5 8.5v7h-3v-3H7v3H4v-7.5Zm4.1-1.3h15.8l-2.3-5.4H10.4l-2.3 5.4ZM9 22a2 2 0 1 0 0-4 2 2 0 0 0 0 4Zm14 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4Z"/></svg></span><span>rent<span class="brand-ride">ride</span></span></a><div class="dash-side-label">${isOwner?'OWNER WORKSPACE':'RENTER SPACE'}</div><nav class="dash-tabs">${(isOwner?['overview','vehicles','bookings','messages']:['overview','bookings']).map(t=>`<button class="${active===t?'active':''}" data-tab="${t}"><span>${({overview:'◫',vehicles:'▣',bookings:'▤',messages:'✉'})[t]}</span>${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</nav><div class="dash-side-bottom"><div class="dash-user"><img src="${escapeHtml(me.avatar||'https://i.pravatar.cc/100?img=12')}" alt=""><span><b>${escapeHtml(me.name)}</b><small>${isOwner?'Vehicle owner':'Renter account'}</small></span></div>${me.is_owner?`<button class="dash-mode-toggle" onclick="openDashboard('overview','${isOwner?'renter':'owner'}')">Switch to ${isOwner?'renter':'owner'} dashboard ↗</button>`:`<button class="dash-mode-toggle" onclick="closeModal();ownerCta()">Enable owner workspace ↗</button>`}<button class="dash-signout" onclick="logout();closeModal()">Sign out ↗</button></div></aside><div class="dash-main"><header class="dash-topbar"><div><small>RENT RIDE · ${isOwner?'OWNER CENTER':'MY RIDES'}</small><b>Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${escapeHtml(me.name.split(' ')[0])}</b></div><div class="dash-top-actions">${isOwner?'<button class="btn btn-dark" id="topAddVehicle">+ List a vehicle</button>':'<button class="btn btn-dark" id="topExploreRides">Find a ride <span>→</span></button>'}<button class="small-btn" onclick="closeModal()">Back to RentRide</button></div></header><main class="dash-page"><div class="dash-page-heading"><div><span class="eyebrow muted">${isOwner?'GROW YOUR RENTRIDE BUSINESS':'YOUR PERSONAL SPACE'}</span><h1>${isOwner?({overview:'Owner overview',vehicles:'Your vehicles',bookings:'Booking requests',messages:'Your inbox'})[active]:({overview:'Renter dashboard',bookings:'My bookings'})[active]}</h1><p>${isOwner?'Keep your listings, bookings and renter conversations in one place.':'Your bookings and upcoming journeys, all in one place.'}</p></div><span class="dash-date">${new Date().toLocaleDateString([], {weekday:'long',month:'long',day:'numeric'})}</span></div><div class="dashboard-content">${content}</div></main></div></section>`,true);$('#modalBackdrop').classList.add('dashboard-backdrop');$('#modal').classList.add('dashboard-modal');$$('.dash-tabs button').forEach(b=>b.onclick=()=>{active=b.dataset.tab;render()});$$('[data-tab]').filter(b=>!b.closest('.dash-tabs')).forEach(b=>b.onclick=()=>{active=b.dataset.tab;render()});if($('#addVehicle'))$('#addVehicle').onclick=()=>vehicleForm();if($('#topAddVehicle'))$('#topAddVehicle').onclick=()=>vehicleForm();if($('#topExploreRides'))$('#topExploreRides').onclick=()=>{closeModal();$('#vehicles').scrollIntoView({behavior:'smooth'})};if($('#exploreRides'))$('#exploreRides').onclick=()=>{closeModal();$('#vehicles').scrollIntoView({behavior:'smooth'})};if($('#openFirstChat'))$('#openFirstChat').onclick=()=>{closeModal();loadVehicles();$('#vehicles').scrollIntoView({behavior:'smooth'})};$$('[data-book-status]').forEach(b=>b.onclick=()=>changeBooking(b.dataset.bookStatus,b.dataset.id,render));$$('[data-handover]').forEach(b=>b.onclick=()=>openHandover(b.dataset.handover));$$('[data-report]').forEach(b=>b.onclick=()=>openReport(b.dataset.report));$$('[data-edit-vehicle]').forEach(b=>b.onclick=()=>vehicleForm(all.find(v=>v.id===Number(b.dataset.editVehicle))));$$('[data-delete-vehicle]').forEach(b=>b.onclick=()=>deleteVehicle(b.dataset.deleteVehicle,render));$$('[data-chat-vehicle]').forEach(b=>b.onclick=()=>{const v=all.find(x=>x.id===Number(b.dataset.chatVehicle));startChat(v)});if(active==='messages'&&isOwner)loadInbox(all)};render()}catch(e){notify(e.message,'error')}}
async function loadInbox(all){try{const messages=await api('/api/messages'),byVehicle=new Map();messages.forEach(m=>{if(!byVehicle.has(m.vehicle_id))byVehicle.set(m.vehicle_id,[]);byVehicle.get(m.vehicle_id).push(m)});const list=$('#inboxList');if(!list)return;if(!byVehicle.size){list.innerHTML='<span>✉</span>No conversations yet. Messages from renters will appear here.';return}list.className='dash-list';list.innerHTML=[...byVehicle].map(([id,items])=>{const v=all.find(x=>x.id===Number(id));const last=items.at(-1);return `<div class="dash-item"><img src="${escapeHtml(v?.image||'')}" alt=""><span class="dash-item-main"><b>${escapeHtml(v?.name||last.vehicle_name)} · ${escapeHtml(last.sender_name)}</b><small>${escapeHtml(last.body)} · ${new Date(last.created_at+'Z').toLocaleString()}</small></span><button class="small-btn primary" data-inbox-chat="${id}">Open chat</button></div>`}).join('');$$('[data-inbox-chat]').forEach(b=>b.onclick=()=>startChat(all.find(v=>v.id===Number(b.dataset.inboxChat))))}catch(e){notify(e.message,'error')}}
window.openDashboard=openDashboard;
function inventoryList(rows){return rows.length?`<div class="dash-list">${rows.map(v=>`<div class="dash-item"><img src="${escapeHtml(v.image)}" alt=""><span class="dash-item-main"><b>${escapeHtml(v.name)}</b><small>${escapeHtml(v.category)} · ${escapeHtml(v.location)} · ${money(v.price)}/hr</small></span><span class="dash-item-actions"><button class="small-btn" data-edit-vehicle="${v.id}">Edit</button><button class="small-btn danger" data-delete-vehicle="${v.id}">Delete</button></span></div>`).join('')}</div>`:'<div class="empty-state"><span>🚘</span>You haven’t listed a vehicle yet.<br><br><button class="small-btn primary" id="addVehicle">List your first ride</button></div>'}
function bookingList(rows,isOwner){if(!rows.length)return '<div class="empty-state"><span>◷</span>No booking requests yet. When you book a ride, it will show up here.</div>';return `<div class="dash-list">${rows.map(b=>`<div class="dash-item"><img src="${escapeHtml(b.image)}" alt=""><span class="dash-item-main"><b>${escapeHtml(b.vehicle_name)}</b><small>${isOwner?'Renter: '+escapeHtml(b.renter_name):'Owner: '+escapeHtml(b.owner_name)} · ${new Date(b.start_at).toLocaleString([], {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})} · ${b.hours}h · ${money(b.total)}${b.offer_id&&b.rate_per_hour?` · ${money(b.rate_per_hour)}/hr negotiated`:''}</small><small>Status: <strong style="color:${b.status==='accepted'?'#25825f':b.status==='rejected'||b.status==='cancelled'?'#b7495b':'#b1802d'}">${escapeHtml(b.status)}</strong></small></span><span class="dash-item-actions">${b.status==='pending'?(isOwner?`<button class="small-btn primary" data-book-status="accepted" data-id="${b.id}">Accept</button><button class="small-btn danger" data-book-status="rejected" data-id="${b.id}">Reject</button>`:`<button class="small-btn danger" data-book-status="cancelled" data-id="${b.id}">Cancel</button>`):''}${b.status==='accepted'?`<button class="small-btn primary" data-handover="${b.id}">Handover</button>`:''}${b.handover_state==='returned'?`<button class="small-btn primary" data-report="${b.id}">View report</button>`:''}${isOwner?`<button class="small-btn" data-chat-vehicle="${b.vehicle_id}">Chat</button>`:''}</span></div>`).join('')}</div>`}
async function changeBooking(status,id,refresh){try{await api('/api/bookings/'+id,{method:'PATCH',body:JSON.stringify({status})});notify(`Booking ${status}.`);openDashboard('bookings',status==='cancelled'?'renter':'owner')}catch(e){notify(e.message,'error')}}
async function deleteVehicle(id){try{await api('/api/vehicles/'+id,{method:'DELETE'});notify('Vehicle removed from your listings.');openDashboard()}catch(e){notify(e.message,'error')}}
function vehicleForm(v=null){openModal(`<h2 class="dash-title">${v?'Edit your vehicle':'List a vehicle'}</h2><p class="dash-subtitle">Add your ride details, then choose its pickup point on the map.</p><form id="vehicleForm" class="form-stack" enctype="multipart/form-data"><div class="form-row"><label>Vehicle name<input name="name" required value="${escapeHtml(v?.name||'')}" placeholder="e.g. Hyundai Creta"></label><label>Category<select name="category" required>${categories.map(([c])=>`<option ${v?.category===c?'selected':''}>${c}</option>`).join('')}</select></label></div><div class="form-row"><label>Hourly price (₹)<input name="price" type="number" min="1" required value="${v?.price||''}" placeholder="190"></label><label>Pickup area or address<div class="location-search-row"><input name="location" id="vehicleLocationName" required value="${escapeHtml(v?.location||'')}" placeholder="Search e.g. Jubilee Hills"><button type="button" class="small-btn primary" id="searchVehicleLocation">Find</button></div></label></div><div class="location-picker-label"><span><b>Exact pickup point</b><small>Search an area, use your location, or tap the map to drop a pin.</small></span><button type="button" class="small-btn" id="useVehicleLocation">◎ Use my location</button></div><div id="vehicleLocationMap" class="vehicle-location-map"></div><div class="location-status" id="vehicleLocationStatus">${v?'Pickup pin saved. Tap the map to move it.':'Choose a pickup point to continue.'}</div><input type="hidden" name="lat" id="vehicleLat" required value="${v?.lat??''}"><input type="hidden" name="lng" id="vehicleLng" required value="${v?.lng??''}"><div class="form-row"><label>Brand<input name="brand" value="${escapeHtml(v?.brand||'')}" placeholder="Hyundai"></label><label>Year<input name="model_year" type="number" value="${v?.model_year||2024}"></label></div><div class="form-row"><label>Vehicle registration number<input name="registration_no" value="${escapeHtml(v?.registration_no||'')}" placeholder="TS09 AB 1234" required></label><label>Seats<input name="seats" type="number" min="1" value="${v?.seats||2}"></label><label>Fuel<select name="fuel"><option ${v?.fuel==='Petrol'?'selected':''}>Petrol</option><option ${v?.fuel==='Diesel'?'selected':''}>Diesel</option><option ${v?.fuel==='Electric'?'selected':''}>Electric</option><option ${v?.fuel==='Hybrid'?'selected':''}>Hybrid</option></select></label></div><div class="form-row"><label>Transmission<select name="transmission"><option>Automatic</option><option ${v?.transmission==='Manual'?'selected':''}>Manual</option></select></label><label>Availability<select name="available"><option value="true" ${v?.available!==0?'selected':''}>Available to book</option><option value="false" ${v?.available===0?'selected':''}>Temporarily unavailable</option></select></label></div><label>Description<textarea name="description" rows="3" placeholder="What makes this ride special?">${escapeHtml(v?.description||'')}</textarea></label><label>Vehicle photos<input name="photos" type="file" accept="image/jpeg,image/png,image/webp" multiple ${v?'':'required'}><span class="inline-note">JPEG, PNG or WebP, up to 6 MB each.</span></label><button class="btn btn-dark">${v?'Save changes':'Publish vehicle'} <span>→</span></button></form>`);initVehicleLocationPicker(v);$('#searchVehicleLocation').onclick=()=>searchVehicleLocation();$('#useVehicleLocation').onclick=()=>useDeviceLocation();$('#vehicleForm').onsubmit=async e=>{e.preventDefault();try{const form=new FormData(e.currentTarget);await api('/api/vehicles'+(v?'/'+v.id:''),{method:v?'PUT':'POST',body:form});notify(v?'Vehicle updated.':'Your vehicle is live!');openDashboard(v?'vehicles':'overview','owner')}catch(err){notify(err.message,'error')}}}
function initVehicleLocationPicker(vehicle){if(!window.L)return;const lat=Number(vehicle?.lat)||17.4326,lng=Number(vehicle?.lng)||78.4071;setTimeout(()=>{const el=$('#vehicleLocationMap');if(!el)return;map=L.map(el).setView([lat,lng],vehicle?14:12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);vehicleMarker=vehicle?L.marker([lat,lng]).addTo(map):null;map.on('click',e=>setVehiclePickup(e.latlng.lat,e.latlng.lng,true));map.invalidateSize()},120)}
async function setVehiclePickup(lat,lng,lookup=false,label=''){if(!Number.isFinite(lat)||!Number.isFinite(lng))return;$('#vehicleLat').value=lat.toFixed(6);$('#vehicleLng').value=lng.toFixed(6);$('#vehicleLat').dispatchEvent(new Event('change'));$('#vehicleLng').dispatchEvent(new Event('change'));if(map){if(vehicleMarker)vehicleMarker.setLatLng([lat,lng]);else vehicleMarker=L.marker([lat,lng]).addTo(map);map.setView([lat,lng],Math.max(map.getZoom(),14))}const status=$('#vehicleLocationStatus');status.textContent='Pickup point selected. Loading nearby address…';if(label){$('#vehicleLocationName').value=label;status.textContent='Pickup point set to '+label+'.';return}if(!lookup){status.textContent='Pickup pin saved.';return}try{const response=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lng}&zoom=18&addressdetails=1`,{headers:{'Accept-Language':'en'}});if(!response.ok)throw new Error('Address lookup unavailable');const data=await response.json(),a=data.address||{},area=a.suburb||a.neighbourhood||a.quarter||a.city_district||a.town||a.city||a.village;const name=area?`${area}${a.city||a.town?' · '+(a.city||a.town):''}`:data.display_name?.split(',').slice(0,2).join(',');if(name)$('#vehicleLocationName').value=name;status.textContent=name?`Pickup point set near ${name}.`:'Pickup pin saved. Add a nearby area or landmark above.'}catch{status.textContent='Pickup pin saved. Add a nearby area or landmark above.'}}
async function searchVehicleLocation(){const input=$('#vehicleLocationName'),query=input.value.trim();if(!query){notify('Enter an area or address to search on the map.','info');input.focus();return}const button=$('#searchVehicleLocation');button.disabled=true;button.textContent='…';try{const response=await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=1&country=India&q=${encodeURIComponent(query+', Hyderabad')}`,{headers:{'Accept-Language':'en'}});if(!response.ok)throw new Error('Location search is unavailable. Try tapping the map.');const places=await response.json();if(!places.length)throw new Error('No matching Hyderabad location found. Try a nearby landmark.');const p=places[0];map?.setView([Number(p.lat),Number(p.lon)],15);await setVehiclePickup(Number(p.lat),Number(p.lon),false,query)}catch(e){notify(e.message,'error')}finally{button.disabled=false;button.textContent='Find'}}
function useDeviceLocation(){if(!navigator.geolocation){notify('Your browser does not support location sharing. Search an area or tap the map instead.','error');return}const button=$('#useVehicleLocation');button.disabled=true;button.textContent='Finding you…';navigator.geolocation.getCurrentPosition(async pos=>{await setVehiclePickup(pos.coords.latitude,pos.coords.longitude,true);button.disabled=false;button.textContent='◎ Use my location'},()=>{button.disabled=false;button.textContent='◎ Use my location';notify('Could not get your location. Allow location access or tap the map instead.','error')},{enableHighAccuracy:true,timeout:12000,maximumAge:30000})}
function searchNow(){if($('#heroCategory').value)$('#categorySelect').value=$('#heroCategory').value;const loc=$('#locationInput').value.trim();if(loc&&!/^(hyderabad(, india)?|near me)$/i.test(loc)&&!$('#queryInput').value.trim())$('#queryInput').value=loc;if(loc&&!/hyderabad/i.test(loc)&&!geo)notify('Showing rides matching your area in Hyderabad.','info');loadVehicles();$('#vehicles').scrollIntoView({behavior:'smooth'})}
$('#searchForm').onsubmit=e=>{e.preventDefault();searchNow()};$('#applyFilters').onclick=()=>{showCount=8;loadVehicles()};$('#sortSelect').onchange=loadVehicles;if($('#verifiedOnly'))$('#verifiedOnly').onchange=loadVehicles;$('#loadMore').onclick=()=>{showCount+=8;renderVehicles()};$('#filterToggle').onclick=()=>$('#filterBar').classList.toggle('open');$('#locateBtn').onclick=()=>{if(!navigator.geolocation){notify('Location isn’t available in this browser.','error');return}navigator.geolocation.getCurrentPosition(pos=>{geo={lat:pos.coords.latitude,lng:pos.coords.longitude};$('#locationInput').value='Near me';$('#sortSelect').value='nearest';loadVehicles();notify('Sorting rides by your location.')},()=>notify('Could not access your location. Check browser permissions.','error'),{enableHighAccuracy:true,timeout:10000})};$('#modalBackdrop').onclick=e=>{if(e.target===$('#modalBackdrop'))closeModal()};document.addEventListener('submit',e=>{if(e.target.id==='vehicleForm'&&(!$('#vehicleLat')?.value||!$('#vehicleLng')?.value)){e.preventDefault();e.stopImmediatePropagation();notify('Choose the pickup point on the map, or use your current location.','error')}},true);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('#mobileMenu').onclick=()=>{const nav=$('.main-nav');nav.style.display=nav.style.display==='flex'?'none':'flex';if(nav.style.display==='flex'){nav.style.position='absolute';nav.style.top='61px';nav.style.left='0';nav.style.right='0';nav.style.background='#fff';nav.style.padding='12px 20px';nav.style.boxShadow='0 8px 18px #28264112';nav.style.justifyContent='center'}};
function init(){renderCategories();$('#heroDate').value=new Date(Date.now()+3600000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);loadVehicles();api('/api/auth/me').then(({user})=>{me=user;updateHeader();connectSocket()}).catch(()=>updateHeader())}
init();

