window.planTrip=()=>{openModal(`<div class="auth-head"><h2>Plan my trip</h2><p>Tell us what you need and we’ll find a good fit.</p></div><form id="tripForm" class="form-stack"><label>People<input name="people" type="number" min="1" max="50" value="2" required></label><label>Distance (km)<input name="distance_km" type="number" min="0.5" max="1000" step="0.5" value="18" required></label><label>Luggage<select name="luggage"><option>none</option><option>small</option><option selected>medium</option><option>large</option></select></label><label>Hours (optional)<input name="hours" type="number" min="1" max="72" placeholder="Estimate for me"></label><button class="btn btn-dark">Find the best vehicle →</button></form><div id="tripResults"></div>`);$('#tripForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));b.people=Number(b.people);b.distance_km=Number(b.distance_km);b.hours=b.hours?Number(b.hours):undefined;const loc=JSON.parse(localStorage.getItem('rr_loc')||'null');if(loc?.lat&&loc?.lng){b.lat=loc.lat;b.lng=loc.lng}try{const data=await api('/api/recommend',{method:'POST',body:JSON.stringify(b)}),out=$('#tripResults');if(!data.recommendations.length){out.innerHTML=`<div class="empty-state">${escapeHtml(data.note||data.split_suggestion?.message||'No suitable rides are available right now.')}</div>`;return}out.innerHTML=data.recommendations.map(x=>`<article class="stat-card" style="margin:10px 0"><b>${escapeHtml(x.label)} ${x.best?'· Best match':''} ${x.tag?'· '+escapeHtml(x.tag):''}</b><p>${escapeHtml(x.reason)}</p><strong>${money(x.estimated_total)}</strong><small style="display:block">${x.available_count} available${x.nearest_distance_km==null?'':` · nearest ${x.nearest_distance_km} km away`}</small><button class="small-btn primary" data-plan-type="${x.type}">Show nearest ${escapeHtml(x.label)}</button></article>`).join('');$$('[data-plan-type]').forEach(btn=>btn.onclick=()=>{const map={car:'Cars',suv:'SUVs',bike:'Bikes',scooter:'Scooters',bicycle:'Bicycles',van:'Vans and Cargo'};$('#categorySelect').value=map[btn.dataset.planType];closeModal();loadVehicles();$('#vehicles').scrollIntoView({behavior:'smooth'})})}catch(err){notify(err.message,'error')}}};
$('#planTripButton').onclick=window.planTrip;
window.openProfile=async()=>{if(!me){authForm('login');return}try{const [prefs,logs]=await Promise.all([api('/api/notifications/prefs'),api('/api/notifications/log')]);openModal(`<div class="auth-head"><h2>Profile</h2><p>Phone verification is a basic check, not a government verification.</p></div><section class="stat-card"><b>Phone verification</b><p>${me.phone?'Phone ending '+escapeHtml(String(me.phone).slice(-4)):'No phone added'} · ${me.phone_verified?'Verified':'Not verified'}</p><form id="otpSend" class="form-row"><input name="phone" placeholder="10 digit phone number" required><button class="small-btn primary">Send OTP</button></form><form id="otpVerify" class="form-row"><input name="otp" placeholder="OTP" required><button class="small-btn">Verify</button></form><small>Demo mode: OTP is shown on screen. In production it would arrive by SMS.</small></section>${me.role==='renter'?`<section class="stat-card" style="margin-top:10px"><b>Driving licence</b><p>Format check only. This is not government verification.</p><form id="licenseForm"><input name="license_no" placeholder="TS09 20190012345"><button class="small-btn primary">Save licence</button></form></section>`:''}<section class="stat-card" style="margin-top:10px"><b>Notifications</b>${prefs.email_enabled_on_server?'':`<p style="color:#a76b08">Email is not configured on the server yet (see .env).</p>`}<label><input id="notifyEmail" type="checkbox" ${prefs.notify_email?'checked':''}> Email (${escapeHtml(prefs.email)})</label><br><label><input id="notifySms" type="checkbox" ${prefs.notify_sms?'checked':''} ${prefs.phone_verified?'':'disabled'}> SMS (${prefs.phone_verified?'verified phone':'verify your phone first'})</label><p><button id="savePrefs" class="small-btn primary">Save settings</button> <button id="testNotify" class="small-btn">Send test notification</button> <button id="enableDesktop" class="small-btn">Enable desktop alerts</button></p><div id="notifyLogs">${logs.map(x=>`<p>${escapeHtml(x.channel)} · ${escapeHtml(x.kind)} · ${escapeHtml(x.status)} · ${escapeHtml(x.created_at)}</p>`).join('')}</div></section>`);$('#otpSend').onsubmit=async e=>{e.preventDefault();try{const x=await api('/api/auth/phone/send-otp',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});if(x.demo_otp)notify('Demo OTP: '+x.demo_otp);else notify(x.message)}catch(x){notify(x.message,'error')}};$('#otpVerify').onsubmit=async e=>{e.preventDefault();try{await api('/api/auth/phone/verify',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});notify('Phone verified.');openProfile()}catch(x){notify(x.message,'error')}};if($('#licenseForm'))$('#licenseForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/users/me/license',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});notify('Licence saved.');}catch(x){notify(x.message,'error')}};$('#savePrefs').onclick=async()=>{try{await api('/api/notifications/prefs',{method:'PUT',body:JSON.stringify({notify_email:$('#notifyEmail').checked,notify_sms:$('#notifySms').checked})});notify('Notification settings saved.')}catch(e){notify(e.message,'error')}};$('#testNotify').onclick=async()=>{try{await api('/api/notifications/test',{method:'POST',body:'{}'});notify('Test notification queued.')}catch(e){notify(e.message,'error')}};$('#enableDesktop').onclick=async()=>{if('Notification' in window){const result=await Notification.requestPermission();notify(result==='granted'?'Desktop alerts enabled.':'Desktop alerts were not enabled.',result==='granted'?'success':'info')}else notify('Desktop alerts are not supported in this browser.','info')}}catch(e){notify(e.message,'error')}};
const previousHeaderUpdate=updateHeader;updateHeader=function(){previousHeaderUpdate();if(me){const b=document.createElement('button');b.className='btn btn-outline';b.textContent='Profile';b.onclick=window.openProfile;$('#headerActions').prepend(b)}};
const previousVehicleForm=vehicleForm;vehicleForm=function(v=null){previousVehicleForm(v);const price=$('#vehicleForm input[name=price]');if(!price)return;const card=document.createElement('div');card.className='stat-card';card.innerHTML='<b>Fair price advisor</b><p id="priceAdvice">Choose a vehicle type and price to see nearby comparables.</p><button type="button" id="useAdvice" class="small-btn primary">Use suggested price</button>';price.closest('.form-row').after(card);const update=async()=>{const category=$('#vehicleForm select[name=category]').value,type=({Cars:'car',SUVs:'suv',Bikes:'bike',Scooters:'scooter',Bicycles:'bicycle','Vans and Cargo':'van'})[category],lat=$('#vehicleLat').value,lng=$('#vehicleLng').value,year=$('#vehicleForm input[name=model_year]').value;if(!type)return;try{const qs=new URLSearchParams({type,model_year:year});if(lat&&lng){qs.set('lat',lat);qs.set('lng',lng)}if(v)qs.set('exclude_id',v.id);const x=await api('/api/owner/price-suggestion?'+qs);$('#priceAdvice').textContent=x.suggested==null?x.message:`Suggested ${money(x.suggested)}/hr · typical range ${money(x.low)} to ${money(x.high)} based on ${x.count} similar vehicles (${x.scope}).`;$('#useAdvice').onclick=()=>{if(x.suggested)price.value=x.suggested}}catch(e){$('#priceAdvice').textContent=e.message}};let timer;$('#vehicleForm select[name=category]').addEventListener('change',update);$('#vehicleForm input[name=model_year]').addEventListener('input',update);price.addEventListener('input',update);setTimeout(update,250)};
window.addEventListener('focus',()=>{document.title='RentRide — Find your next ride'});document.addEventListener('visibilitychange',()=>{if(!document.hidden)document.title='RentRide — Find your next ride'});
window.openHandover=async id=>{try{const data=await api(`/api/bookings/${id}/handover`),b=data.booking;const checklist=(data.pickup?.checklist||data.return?.checklist||{}),checks=Object.keys(checklist);const stage=data.can.submit_pickup?'pickup':data.can.submit_return?'return':data.can.confirm_pickup?'pickup':data.can.confirm_return?'return':null;let body='';if(data.can.submit_pickup||data.can.submit_return){const keys=({Cars:['documents_checked','keys_handed','body_condition_ok','tyres_ok','lights_ok','brakes_ok','interior_clean','spare_wheel_and_tools'],SUVs:['documents_checked','keys_handed','body_condition_ok','tyres_ok','lights_ok','brakes_ok','interior_clean','spare_wheel_and_tools'],'Vans and Cargo':['documents_checked','keys_handed','body_condition_ok','tyres_ok','lights_ok','brakes_ok','interior_clean','spare_wheel_and_tools'],Bikes:['documents_checked','keys_handed','body_condition_ok','tyres_ok','lights_ok','brakes_ok','helmet_provided'],Scooters:['documents_checked','keys_handed','body_condition_ok','tyres_ok','lights_ok','brakes_ok','helmet_provided'],Bicycles:['keys_handed','body_condition_ok','tyres_ok','brakes_ok','chain_gears_ok','helmet_provided']})[b.category]||[];body=`<form id="handoverForm" class="form-stack"><h3>Record ${stage}</h3>${keys.map(k=>`<label><input type="checkbox" name="${k}" checked> ${escapeHtml(k.replaceAll('_',' '))}</label>`).join('')||keys.map(k=>`<label><input type="checkbox" name="${k}" checked> ${escapeHtml(k.replaceAll('_',' '))}</label>`).join('')}<div class="form-row"><label>Odometer km<input name="odometer_km" type="number" min="0" required></label><label>Fuel or battery %<input name="level_percent" type="number" min="0" max="100" value="80" required></label></div><label>Notes<textarea name="notes"></textarea></label><label>Damage notes<textarea name="damage_notes"></textarea></label>${['front','back','left','right'].map(x=>`<label>${x[0].toUpperCase()+x.slice(1)} photo<input type="file" data-photo-label="${x}" accept="image/jpeg,image/png,image/webp" capture="environment" required></label>`).join('')}<button class="btn btn-dark">Submit checklist</button></form>`}else if(data.can.confirm_pickup||data.can.confirm_return){const check=stage==='pickup'?data.pickup:data.return;body=`<h3>Review ${stage}</h3><p>Odometer: ${check?.odometer_km??'—'} km · Level: ${check?.level_percent??'—'}%</p><p>${escapeHtml(check?.notes||'')}</p><div>${(check?.photos||[]).map(p=>`<img src="${escapeHtml(p.url)}" alt="${escapeHtml(p.label)}" style="width:100px;height:70px;object-fit:cover;margin:4px">`).join('')}</div><button id="confirmHandover" class="btn btn-dark">Confirm</button> <button id="disputeHandover" class="small-btn danger">Dispute</button>`}else{body=`<p>Current handover state: <b>${escapeHtml(b.handover_state)}</b></p>${data.pickup?`<p>Pickup: ${escapeHtml(data.pickup.status)}</p>`:''}${data.return?`<p>Return: ${escapeHtml(data.return.status)}</p>`:''}`}openModal(`<div class="auth-head"><h2>${escapeHtml(b.vehicle_name)} handover</h2><p>${escapeHtml(b.owner_name)} · ${escapeHtml(b.renter_name)} · ${escapeHtml(b.handover_state)}</p></div>${body}`);if($('#handoverForm'))$('#handoverForm').onsubmit=async e=>{e.preventDefault();const form=new FormData(),checks={};e.currentTarget.querySelectorAll('input[type=checkbox]').forEach(c=>checks[c.name]=c.checked);form.append('checklist',JSON.stringify(checks));form.append('labels',JSON.stringify(['front','back','left','right']));for(const f of e.currentTarget.querySelectorAll('input[type=file]'))if(f.files[0])form.append('photos',f.files[0]);for(const [k,v] of new FormData(e.currentTarget))if(k!=='checklist')form.append(k,v);try{await api(`/api/bookings/${id}/handover/${stage}`,{method:'POST',body:form});notify('Handover checklist submitted.');openHandover(id)}catch(x){notify(x.message,'error')}};if($('#confirmHandover'))$('#confirmHandover').onclick=()=>respond('confirm');if($('#disputeHandover'))$('#disputeHandover').onclick=()=>{const note=prompt('Describe the issue (at least 10 characters)');if(note)respond('dispute',note)};async function respond(action,note=''){try{await api(`/api/bookings/${id}/handover/${stage}/respond`,{method:'POST',body:JSON.stringify({action,note})});notify('Handover updated.');openHandover(id)}catch(e){notify(e.message,'error')}}}catch(e){notify(e.message,'error')}};
window.openReport=async id=>{try{const d=await api(`/api/bookings/${id}/handover/report`);openModal(`<div class="auth-head"><h2>Handover report</h2><p>${escapeHtml(d.vehicle.name)} · ${escapeHtml(d.state)}</p></div><div class="stats-grid"><div class="stat-card"><small>KM DRIVEN</small><b>${d.summary.km_driven??'—'}</b></div><div class="stat-card"><small>FUEL / BATTERY CHANGE</small><b>${d.summary.level_change??'—'}%</b></div><div class="stat-card"><small>NEW DAMAGE</small><b>${d.summary.new_damage_reported?'Reported':'None reported'}</b></div></div><p>Checklist changes: ${escapeHtml(d.summary.checklist_regressions.join(', ')||'None')}</p>${d.summary.photo_pairs.map(x=>`<section class="stat-card"><b>${escapeHtml(x.label)}</b><div>${x.pickup?`<img src="${escapeHtml(x.pickup)}" alt="${x.label} pickup" style="width:45%">`:''}${x.return?`<img src="${escapeHtml(x.return)}" alt="${x.label} return" style="width:45%">`:''}</div></section>`).join('')}<button class="btn btn-dark" id="printReport">Print / Save as PDF</button>`);$('#printReport').onclick=()=>window.print()}catch(e){notify(e.message,'error')}};
